	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void standaloneTupleQueryReplaysAfterCustomFunctionBarrier(@TempDir Path dataDirectory) throws Exception {
		String functionIri = "urn:rdf4j:standalone-query-replay:function:" + UUID.randomUUID();
		ReplayBarrierFunction function = new ReplayBarrierFunction(functionIri);
		FunctionRegistry functionRegistry = FunctionRegistry.getInstance();
		LmdbStore store = newStore(dataDirectory);
		SailRepository repository = new SailRepository(store);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			functionRegistry.add(function);
			repository.init();
			try (RepositoryConnection seed = repository.getConnection()) {
				seed.add(SUBJECT, VALUE_PREDICATE, Values.literal("before"));
			}

			TripleStore tripleStore = tripleStoreOf(store);
			long initialMapSize = mapSize(tripleStore);
			LmdbSailStore backingStore = store.getBackingStore();
			MapGrowthMetrics.Snapshot before = backingStore.growthMetricsSnapshot();
			Future<List<String>> query = executor.submit(() -> {
				try (RepositoryConnection reader = repository.getConnection()) {
					String queryString = "SELECT ?value WHERE { <" + SUBJECT + "> <" + VALUE_PREDICATE
							+ "> ?value . FILTER(<" + functionIri + ">(?value)) }";
					TupleQuery tupleQuery = reader.prepareTupleQuery(QueryLanguage.SPARQL, queryString);
					try (TupleQueryResult result = tupleQuery.evaluate()) {
						List<String> values = new ArrayList<>();
						while (result.hasNext()) {
							values.add(result.next().getValue("value").stringValue());
						}
						return values;
					}
				}
			});

			assertThat(function.awaitFirstInvocation()).isTrue();
			String namespace = publishGrowth(repository, initialMapSize, backingStore, before);
			assertThat(function.invocationCount()).isEqualTo(1);
			function.releaseFirstInvocation();
			assertThat(function.awaitRepeatedInvocation()).isTrue();

			assertThat(query.get(15, TimeUnit.SECONDS)).containsExactlyInAnyOrder("before", "after");
			awaitTripleStoreGrowth(repository, tripleStore, initialMapSize, namespace);
			assertThat(function.invocationCount()).isGreaterThan(1);
		} finally {
			function.releaseFirstInvocation();
			executor.shutdown();
			boolean terminated;
			try {
				terminated = executor.awaitTermination(5, TimeUnit.SECONDS);
				if (!terminated) {
					executor.shutdownNow();
					terminated = executor.awaitTermination(5, TimeUnit.SECONDS);
				}
			} finally {
				functionRegistry.remove(function);
				repository.shutDown();
			}
			assertThat(terminated).isTrue();
		}
	}

	private static LmdbStore newStore(Path dataDirectory) {
		return new LmdbStore(dataDirectory.toFile(), new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(GROWTH_MAP_SIZE)
				.setValueDBSize(GROWTH_MAP_SIZE)
				.setMapGrowthThreshold(GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(150));
	}

	private static String publishGrowth(SailRepository repository, long initialMapSize,
			LmdbSailStore backingStore, MapGrowthMetrics.Snapshot before) throws Exception {
		Model growth = new LinkedHashModel();
		int namespaceBytes = Math.toIntExact(Math.round(initialMapSize * SOFT_GROWTH_DEMAND_RATIO));
		String namespace = "urn:rdf4j:standalone-query-replay:growth-namespace:" + "n".repeat(namespaceBytes);
		for (int i = 0; i < 10_000; i++) {
			growth.add(Values.iri("urn:rdf4j:standalone-query-replay:growth:" + i), GROWTH_PREDICATE,
					Values.literal("growth"));
		}
		try (RepositoryConnection writer = repository.getConnection()) {
			writer.begin(IsolationLevels.SNAPSHOT);
			writer.setNamespace("growth-demand", namespace);
			writer.add(growth);
			writer.add(SUBJECT, VALUE_PREDICATE, Values.literal("after"));
			writer.commit();
		}
		awaitGrowthEpisode(backingStore, before);
		awaitReplayAccepted(backingStore, before);
		return namespace;
	}

	private static void awaitTripleStoreGrowth(SailRepository repository, TripleStore tripleStore, long initialMapSize,
			String namespace) throws Exception {
		try (RepositoryConnection barrier = repository.getConnection()) {
			barrier.begin(IsolationLevels.SNAPSHOT);
			assertThat(barrier.getNamespace("growth-demand")).isEqualTo(namespace);
			barrier.rollback();
		}
		assertThat(mapSize(tripleStore)).as("the concurrent writer must grow TripleStore")
				.isGreaterThan(initialMapSize);
	}

	private static void awaitGrowthEpisode(LmdbSailStore backingStore, MapGrowthMetrics.Snapshot before) {
		long deadlineNanos = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (backingStore.growthMetricsSnapshot().growthEpisodes() <= before.growthEpisodes()) {
			if (System.nanoTime() >= deadlineNanos) {
				throw new AssertionError("the published namespace did not start a soft map-growth episode");
			}
			Thread.onSpinWait();
		}
	}

	private static void awaitReplayAccepted(LmdbSailStore backingStore, MapGrowthMetrics.Snapshot before) {
		long deadlineNanos = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (backingStore.growthMetricsSnapshot().replayAccepted() <= before.replayAccepted()) {
			if (System.nanoTime() >= deadlineNanos) {
				throw new AssertionError("the soft growth episode did not accept the blocked read for replay");
			}
			Thread.onSpinWait();
		}
	}

	private static String servicePattern(ServiceGate serviceGate) {
		return "SERVICE <" + serviceGate.endpoint() + "> { <" + REMOTE_SUBJECT + "> <" + REMOTE_PREDICATE
				+ "> ?remoteValue }";
	}

	private static TripleStore tripleStoreOf(LmdbStore store) throws ReflectiveOperationException {
		Field field = LmdbSailStore.class.getDeclaredField("tripleStore");
		field.setAccessible(true);
		return (TripleStore) field.get(store.getBackingStore());
	}

	private static long mapSize(TripleStore tripleStore) throws ReflectiveOperationException {
		Field field = TripleStore.class.getDeclaredField("mapSize");
		field.setAccessible(true);
		return field.getLong(tripleStore);
	}

	private static final class ReplayBarrierFunction implements Function {
		private final String functionIri;
		private final CountDownLatch firstInvocation = new CountDownLatch(1);
		private final CountDownLatch repeatedInvocation = new CountDownLatch(1);
		private final CountDownLatch releaseFirstInvocation = new CountDownLatch(1);
		private final AtomicInteger invocationCount = new AtomicInteger();

		private ReplayBarrierFunction(String functionIri) {
			this.functionIri = functionIri;
		}

		@Override
		public String getURI() {
			return functionIri;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) throws ValueExprEvaluationException {
			return valueFactory.createLiteral(true);
		}

		@Override
		public Value evaluate(TripleSource tripleSource, Value... args) throws ValueExprEvaluationException {
			int invocation = invocationCount.incrementAndGet();
			if (invocation == 1) {
				firstInvocation.countDown();
				try {
					if (!releaseFirstInvocation.await(30, TimeUnit.SECONDS)) {
						throw new ValueExprEvaluationException(
								"Timed out waiting to release the first function invocation");
					}
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new ValueExprEvaluationException("Interrupted while waiting at the replay barrier", e);
				}
			} else {
				repeatedInvocation.countDown();
			}
			return tripleSource.getValueFactory().createLiteral(true);
		}

		private boolean awaitFirstInvocation() throws InterruptedException {
			return firstInvocation.await(10, TimeUnit.SECONDS);
		}

		private boolean awaitRepeatedInvocation() throws InterruptedException {
			return repeatedInvocation.await(10, TimeUnit.SECONDS);
		}

		private int invocationCount() {
			return invocationCount.get();
		}

		private void releaseFirstInvocation() {
			releaseFirstInvocation.countDown();
		}
	}

	private static final class ServiceGate implements AutoCloseable {
		private static final byte[] RESULTS = ("<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
				+ "<sparql xmlns=\"http://www.w3.org/2005/sparql-results#\"><head>"
				+ "<variable name=\"remoteValue\"/></head><results><result>"
				+ "<binding name=\"remoteValue\"><literal>service-result</literal></binding>"
				+ "</result></results></sparql>").getBytes(StandardCharsets.UTF_8);

		private final CountDownLatch firstRequest = new CountDownLatch(1);
		private final CountDownLatch secondRequest = new CountDownLatch(1);
		private final CountDownLatch releaseFirst = new CountDownLatch(1);
		private final CountDownLatch releaseSecond = new CountDownLatch(1);
		private final AtomicInteger requestCount = new AtomicInteger();
		private final ExecutorService executor = Executors.newCachedThreadPool();
		private final HttpServer server;

		private ServiceGate() throws IOException {
			server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
			server.setExecutor(executor);
			server.createContext("/sparql", this::handle);
			server.start();
		}

		private String endpoint() {
			return "http://127.0.0.1:" + server.getAddress().getPort() + "/sparql";
		}

		private boolean awaitFirstRequest() throws InterruptedException {
			return firstRequest.await(10, TimeUnit.SECONDS);
		}

		private boolean awaitSecondRequest() throws InterruptedException {
			return secondRequest.await(10, TimeUnit.SECONDS);
		}

		private int requestCount() {
			return requestCount.get();
		}

		private void releaseFirstRequest() {
			releaseFirst.countDown();
		}

		private void releaseAllRequests() {
			releaseFirst.countDown();
			releaseSecond.countDown();
		}

		private void handle(HttpExchange exchange) throws IOException {
			int request = requestCount.incrementAndGet();
			firstRequest.countDown();
			if (request > 1) {
				secondRequest.countDown();
			}
			CountDownLatch release = request == 1 ? releaseFirst : releaseSecond;
			try {
				if (!release.await(30, TimeUnit.SECONDS)) {
					exchange.sendResponseHeaders(503, -1);
					return;
				}
				exchange.getResponseHeaders().set("Content-Type", "application/sparql-results+xml; charset=UTF-8");
				exchange.sendResponseHeaders(200, RESULTS.length);
				exchange.getResponseBody().write(RESULTS);
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			} finally {
				exchange.close();
			}
		}

		@Override
		public void close() {
			releaseAllRequests();
			server.stop(0);
			executor.shutdownNow();
			try {
				executor.awaitTermination(5, TimeUnit.SECONDS);
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			}
		}
	}
